let raw = $input.first().json.output || $input.first().json.text || $input.first().json.query || "";

if(String(raw).trim().toUpperCase().startsWith('ASK:')){
  return {
    query: String(raw).trim(),
    tableName: '-',
    is_clarification: true
  };
}

let match = String(raw).match(/(SELECT|UPDATE|INSERT|DELETE|ALTER|CREATE|DROP|TRUNCATE|EXEC|GRANT|REVOKE|DENY|BACKUP|WITH)[\s\S]*/i);

let cleanQuery = match ? match[0] : String(raw);

cleanQuery = cleanQuery
  .replace(/[{}"]/g, '')
  .replace(/\\n/g, ' ')
  .replace(/```/g, '')
  .replace(/\bjson\b/gi, '')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const tableMatch = cleanQuery.match(/(?:UPDATE|INSERT\s+INTO|DELETE\s+FROM)\s+\[?([a-zA-Z0-9_\.]+)\]?/i);

let tableName = '-'; 

if (tableMatch && tableMatch[1]) {
  tableName = tableMatch[1];
}

return { 
  query: cleanQuery, 
  table_name: tableName
};

const crypto = require('crypto');
const secret = process.env.JWT_SECRET;
if (!secret || secret.length < 32) {
  return { json: { _error: 'Server mis-config: JWT_SECRET belum di-set', _status: 500 } };
}

function verifyJwt(token) {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('Format token tidak valid');
  const [h, p, s] = parts;
  const expected = crypto.createHmac('sha256', secret).update(h + '.' + p).digest('base64url');
  const a = Buffer.from(expected);
  const b = Buffer.from(s);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    throw new Error('Signature token tidak valid');
  }
  return JSON.parse(Buffer.from(p, 'base64url').toString());
}

// --- Security prelude ---
const _headers = $input.first().json.headers || {};
const _authHeader = _headers.authorization || _headers.Authorization || '';
const _rawToken = _authHeader.replace('Bearer ', '');
let _tokenPayload = null;
if (_rawToken) {
  try { _tokenPayload = verifyJwt(_rawToken); } catch (e) {}
  if (_tokenPayload && _tokenPayload.exp && _tokenPayload.exp < Math.floor(Date.now()/1000)) _tokenPayload = null;
}
const _ALLOWED_DB = ['TestDB', 'TestDB4'];
const _bodyRef = $input.first().json.body;
if (_bodyRef) {
  if (_bodyRef.database && !_ALLOWED_DB.includes(_bodyRef.database)) {
    return { json: { success: false, error: 'Database tidak diizinkan: ' + _bodyRef.database, status: 403 } };
  }
  if (_tokenPayload) {
    _bodyRef.userId = _tokenPayload.user_id;
    _bodyRef.userRole = _tokenPayload.role;
  }
  const _roles = ((_bodyRef.userRole) || '').split(',').map(r => r.trim());
  if (!_roles.includes('db_owner')) _bodyRef.direct_execute = false;
}
// --- End security prelude ---

const body = $json.body || $json;
const input = (body.message || "").trim();
const sessionId = body.sessionId || "default";
const database = body.database || "TestDB";
const pendingId = body.pending_id || null;
const directQuery = body.direct_query || "";  
const isDirectExecute = body.direct_execute === true;
const userId = body.userId || null;
const userRole = body.userRole || "db_datareader";

const upper = input.toUpperCase();
let mode = "new";
let query = input;

if (isDirectExecute && directQuery) {
  mode = "direct_execute";
  query = directQuery;
}
if (upper === "CONFIRM" || upper === "YA" || upper === "KONFIRMASI") {
  mode = "confirm";
} else if (upper === "BATAL" || upper === "CANCEL" || upper === "TIDAK") {
  mode = "cancel";
}

return {
  mode: mode,
  query: query,
  original_input: input,
  clean_input: input,
  sessionId: sessionId,
  userId: userId,
  userRole: userRole,
  database: database,
  pending_id: pendingId,
  direct_query: directQuery,
  is_direct_execute: isDirectExecute,
  receivedAt: new Date().toISOString()
};

const query = $json.query || "";
const upperQuery = query.toUpperCase();
const userRole = $('Parse Code').item.json.userRole || $json.userRole || "db_datareader";
const isValidSQL = /^(SELECT|UPDATE|INSERT|DELETE|ALTER|CREATE|DROP|TRUNCATE|EXEC|BACKUP|GRANT|REVOKE|DENY)\s/i.test(query);

const permissions = {
  db_owner: { select: true, dml: true, ddl: true, drop: true },
  db_securityadmin: { select: true, dml: true, ddl: true, drop: true },
  db_accessadmin: { select: true, dml: true, ddl: true, drop: false },
  db_ddladmin: { select: true, dml: false, ddl: true, drop: true },
  db_datawriter: { select: true, dml: true, ddl: false, drop: false },
  db_datareader: { select: true, dml: false, ddl: false, drop: false },
  db_backupoperator:  { select: true, dml: false, ddl: false, drop: false },
  db_denydatareader:  { select: false, dml: false, ddl: false, drop: false },
  db_denydatawriter:  { select: true, dml: false, ddl: true, drop: true }
};

const userRoleList = (userRole || '').split(',').map(r => r.trim()).filter(Boolean);
const userPerm = userRoleList.reduce((acc, role) => {
  const p = permissions[role] || {};
  return {
    select: acc.select || p.select || false,
    dml: acc.dml || p.dml || false,
    ddl: acc.ddl || p.ddl || false,
    drop: acc.drop || p.drop || false
  };
}, { select: false, dml: false, ddl: false, drop: false });

if (query.trim().toUpperCase().startsWith('ASK:')) {
  return {
    query: query,
    table_name: '-',
    is_destructive: false,
    is_error: false,
    is_forbidden: false,
    is_clarification: true,
    classification: 'clarification',
    session_id: $('Parse Code').item.json.sessionId || "default"
  };
}

function extractTableName(q) {
  const trimmed = (q || '').trim();

  const createTableMatch = trimmed.match(/CREATE\s+TABLE\s+(?:\[?dbo\]?\.)?(\[[^\]]+\]|[a-zA-Z0-9_]+)/i);
  if (createTableMatch) return createTableMatch[1].replace(/[\[\]]/g, '');

  const alterTableMatch = trimmed.match(/ALTER\s+TABLE\s+(?:\[?dbo\]?\.)?(\[[^\]]+\]|[a-zA-Z0-9_]+)/i);
  if (alterTableMatch) return alterTableMatch[1].replace(/[\[\]]/g, '');

  const spMatch = trimmed.match(/CREATE\s+(?:OR\s+ALTER\s+)?PROCEDURE\s+(?:\[?dbo\]?\.)?(\[[^\]]+\]|[a-zA-Z0-9_]+)/i) || trimmed.match(/ALTER\s+PROCEDURE\s+(?:\[?dbo\]?\.)?(\[[^\]]+\]|[a-zA-Z0-9_]+)/i);
  if (spMatch) return spMatch[1].replace(/[\[\]]/g, '');

  const dropSpMatch = trimmed.match(/DROP\s+PROCEDURE\s+(?:\[?dbo\]?\.)?(\[[^\]]+\]|[a-zA-Z0-9_]+)/i);
  if (dropSpMatch) return dropSpMatch[1].replace(/[\[\]]/g, '');

  const execMatch = trimmed.match(/EXEC(?:UTE)?\s+(?:\[?dbo\]?\.)?(\[[^\]]+\]|[a-zA-Z0-9_]+)/i);
  if (execMatch) return execMatch[1].replace(/[\[\]]/g, '');

  const viewMatch = trimmed.match(/(?:CREATE|ALTER|DROP)\s+(?:OR\s+ALTER\s+)?VIEW\s+(?:\[?dbo\]?\.)?(\[[^\]]+\]|[a-zA-Z0-9_]+)/i);
  if (viewMatch) return viewMatch[1].replace(/[\[\]]/g, '');

  const backupMatch = trimmed.match(/BACKUP\s+(?:DATABASE|LOG)\s+(?:\[([^\]]+)\]|([a-zA-Z0-9_]+))/i);
  if (backupMatch) return (backupMatch[1] || backupMatch[2] || '-');

  const indexMatch = trimmed.match(/CREATE\s+(?:UNIQUE\s+)?(?:CLUSTERED\s+|NONCLUSTERED\s+)?INDEX\s+(?:\[?([^\]]+)\]?|[a-zA-Z0-9_]+)/i);
  if (indexMatch) return indexMatch[1] || indexMatch[2] || '-';

  const tableMatch = trimmed.match(/\b(?:FROM|JOIN|UPDATE|INTO|DELETE\s+FROM)\s+(\[?[a-zA-Z0-9_]+\]?(?:\.[a-zA-Z0-9_]+)?)/i);
  if (tableMatch) return tableMatch[1].replace(/[\[\]]/g, '');

  return '-';
}

const tableName = extractTableName(query);

let subType = '';
if (/^CREATE\s+TABLE/i.test(upperQuery)) {
  subType = 'create_table';

} else if (/SP_RENAME/i.test(upperQuery)) {
  subType = 'rename_column';

} else if (/^ALTER\s+TABLE/i.test(upperQuery)) {
  if (/DROP\s+COLUMN/i.test(upperQuery)) subType = 'alter_drop_column';
  else if (/ADD\s+/i.test(upperQuery)) subType = 'alter_add_column';
  else if (/FOREIGN\s+KEY/i.test(upperQuery)) subType = 'alter_foreign_key';
  else subType = 'alter_table';

} else if (/^CREATE\s+(?:UNIQUE\s+)?(?:CLUSTERED\s+|NONCLUSTERED\s+)?INDEX/i.test(upperQuery)) {
  subType = 'create_index';

} else if (/^BACKUP\s+DATABASE/i.test(upperQuery)) {
  subType = 'backup_database';

} else if (/^BACKUP\s+LOG/i.test(upperQuery)) {
  subType = 'backup_log';
}

if (!isValidSQL) {
  return { 
    query: query,
    tableName: tableName,
    is_destructive: false, 
    is_error: true,
    is_forbidden: false,
    classification: 'error',
    session_id: $('Parse Code').item.json.sessionId || "default"
  };
}

const isForbidden = 
  /DROP\s+DATABASE/i.test(query) ||
  /CREATE\s+USER/i.test(query) ||
  /ALTER\s+USER/i.test(query) ||
  /DROP\s+USER/i.test(query) ||
  /CREATE\s+LOGIN/i.test(query) ||
  /ALTER\s+LOGIN/i.test(query) ||  
  /DROP\s+LOGIN/i.test(query) ||
  /CREATE\s+ROLE/i.test(query) ||
  /ALTER\s+ROLE/i.test(query) ||
  /DROP\s+ROLE/i.test(query) ||
  /\bGRANT\b/i.test(query) ||
  /\bREVOKE\b/i.test(query) ||
  /\bDENY\b/i.test(query) ||
  /^CREATE\s+(?:UNIQUE\s+)?(?:CLUSTERED\s+|NONCLUSTERED\s+)?INDEX/i.test(query) ||
  /^BACKUP\s+DATABASE/i.test(query) ||
  /^BACKUP\s+LOG/i.test(query) ||
  ((upperQuery.startsWith('UPDATE') || upperQuery.startsWith('DELETE')) && !/\bWHERE\b/i.test(query));

const isDestructive = 
  ((upperQuery.startsWith('UPDATE') || upperQuery.startsWith('DELETE')) && !/\bWHERE\b/i.test(query)) ||
  upperQuery.startsWith('DROP') ||
  upperQuery.startsWith('TRUNCATE') ||
  /ALTER\s+TABLE.*DROP\s+COLUMN/i.test(query) ||
  /CREATE\s+PROCEDURE/i.test(query) ||
  /ALTER\s+PROCEDURE/i.test(query) ||
  /DROP\s+PROCEDURE/i.test(query) ||
  /CREATE\s+VIEW/i.test(query) ||              
  /ALTER\s+VIEW/i.test(query) ||               
  /DROP\s+VIEW/i.test(query) ||
  /^CREATE\s+TABLE/i.test(query) ||             
  /SP_RENAME/i.test(query) ||              
  /^ALTER\s+TABLE/i.test(query);

const isSelect = upperQuery.startsWith('SELECT') || upperQuery.startsWith('EXEC');
const isDML = upperQuery.startsWith('INSERT') || upperQuery.startsWith('UPDATE') || upperQuery.startsWith('DELETE');
const isDDL = upperQuery.startsWith('CREATE') || upperQuery.startsWith('ALTER');
const isDrop = upperQuery.startsWith('DROP') || upperQuery.startsWith('TRUNCATE');

let permissionDenied = false;
let denialReason = '';

if (isSelect && !userPerm.select) {
  permissionDenied = true;
  denialReason = 'Role Anda tidak memiliki hak akses untuk membaca data.';
} else if (isDML && !userPerm.dml) {
  permissionDenied = true;
  denialReason = 'Role Anda tidak memiliki hak akses untuk membuat, mengubah ataupun menambahkan data baru.';
} else if (isDDL && !userPerm.ddl) {
  permissionDenied = true;
  denialReason = 'Role Anda tidak memiliki hak akses untuk menambahkan atau mengubah struktur database.';
} else if (isDrop && !userPerm.drop) {
  permissionDenied = true;
  denialReason = 'Role Anda tidak memiliki hak akses untuk menghapus objek yang ada di database';
}

const finalForbidden = isForbidden || permissionDenied;
let narrative = '';

if (permissionDenied) {
  narrative = `AKSES DITOLAK: ${denialReason}\nRole Anda: ${userRole}`;
} else if (isForbidden) {
  narrative = `AKSES DITOLAK: Operasi ini dilarang untuk semua role.\nRole Anda: ${userRole}`;
}

let classification = 'safe';
if (permissionDenied) {
  classification = 'unauthorized';       
} else if (isForbidden) {
  classification = 'forbidden';          
} else if (isDestructive) {
  classification = 'confirm';
}

return {
  query: query,
  tableName: tableName,
  is_destructive: isDestructive,
  is_error: false,
  is_forbidden: finalForbidden,
  classification: classification,
  sub_type: subType,
  user_role: userRole,
  narrative: narrative,
  session_id: $('Parse Code').item.json.sessionId || "default"
};

function detectQueryType(q) {
  const upper = (q || '').toUpperCase().trim();

  if (/^CREATE\s+OR\s+ALTER\s+PROCEDURE/.test(upper)) return 'CREATE PROCEDURE';
  if (/^CREATE\s+PROCEDURE/.test(upper)) return 'CREATE PROCEDURE';
  if (/^ALTER\s+PROCEDURE/.test(upper)) return 'ALTER PROCEDURE';
  if (/^DROP\s+PROCEDURE/.test(upper)) return 'DROP PROCEDURE';
  if (/^BACKUP\s+DATABASE/.test(upper)) return 'BACKUP DATABASE';
  if (/^CREATE\s+(OR\s+ALTER\s+)?VIEW/.test(upper)) return 'CREATE VIEW';
  if (/^DROP\s+VIEW/.test(upper)) return 'DROP VIEW';
  if (/^ALTER\s+VIEW/.test(upper)) return 'ALTER VIEW';               
  if (/^BACKUP\s+LOG/.test(upper)) return 'BACKUP LOG';
  if (/^CREATE\s+TABLE/.test(upper)) return 'CREATE TABLE';
  if (/^ALTER\s+TABLE/.test(upper)) return 'ALTER TABLE';
  if (/^DROP\s+TABLE/.test(upper)) return 'DROP TABLE';
  if (/^TRUNCATE/.test(upper)) return 'TRUNCATE';
  if (/^SELECT/.test(upper)) return 'SELECT';
  if (/^INSERT/.test(upper)) return 'INSERT';
  if (/^UPDATE/.test(upper)) return 'UPDATE';
  if (/^DELETE/.test(upper)) return 'DELETE';
  if (/^EXEC/.test(upper)) return 'EXEC';
  if (/^GRANT/.test(upper)) return 'GRANT';
  if (/^REVOKE/.test(upper)) return 'REVOKE';
  if (/^DENY/.test(upper)) return 'DENY';

  return 'UNKNOWN';
}

const query = $('Detect Destructive').item.json.query || $('Insert Pending Query ').item.json.query || "";
const table = $('Detect Destructive').item.json.tableName || $('Detect Destructive').item.json.table_name || "-";
const affectedRows = $('Count Affected Rows').item.json.affected_rows || 0;
const database = $('Parse Code').item.json.database || "TestDB";
const subType = $('Detect Destructive').item.json.sub_type || "";

let statusType = "destructive";
let statusText = "Konfirmasi Diperlukan";
let narrativeOverride = "";
let actionType = "melakukan perubahan";

if (subType === 'create_table') {
  statusType = 'confirm_create_table';
  statusText = 'Konfirmasi Pembuatan Tabel';
  actionType = "membuat tabel baru";
} else if (subType === 'rename_column') {
  statusType = 'confirm_rename_column';
  statusText = 'Konfirmasi Ubah Nama Kolom';
  actionType = "mengubah nama kolom";
} else if (subType === 'alter_drop_column') {
  statusType = 'confirm_alter_drop_column';
  statusText = 'Konfirmasi Hapus Kolom';
  actionType = "menghapus kolom (data akan hilang permanen)";
} else if (subType === 'alter_add_column') {
  statusType = 'confirm_alter_add_column';
  statusText = 'Konfirmasi Tambah Kolom';
  actionType = "menambahkan kolom baru";
} else if (subType === 'alter_foreign_key') {
  statusType = 'confirm_alter_foreign_key';
  statusText = 'Konfirmasi Tambah Foreign Key';
  actionType = "menambahkan relasi antar tabel (Foreign Key)";
} else if (subType === 'alter_table') {
  statusType = 'confirm_alter_table';
  statusText = 'Konfirmasi Perubahan Struktur Tabel';
  actionType = "mengubah struktur tabel";
} 

else {
  const qType = detectQueryType(query);
  switch(qType) {
    case 'CREATE PROCEDURE':
      statusText = 'Konfirmasi Buat Stored Procedure';
      actionType = 'membuat Stored Procedure baru';
      break;
    case 'ALTER PROCEDURE':
      statusText = 'Konfirmasi Ubah Stored Procedure';
      actionType = 'mengubah Stored Procedure';
      break;
    case 'DROP PROCEDURE':
      statusText = 'Konfirmasi Hapus Stored Procedure';
      actionType = 'menghapus Stored Procedure secara permanen';
      break;
    case 'CREATE VIEW':
      statusText = 'Konfirmasi Buat View';
      actionType = 'membuat View baru';
      break;
    case 'DROP VIEW':
      statusText = 'Konfirmasi Hapus View';
      actionType = 'menghapus View secara permanen';
      break;
    case 'DROP TABLE':
      statusText = 'Konfirmasi Hapus Tabel';
      actionType = 'menghapus seluruh tabel beserta datanya (SANGAT BERBAHAYA)';
      break;
    case 'TRUNCATE':
      statusText = 'Konfirmasi Kosongkan Tabel';
      actionType = 'mengosongkan seluruh isi tabel (data akan hilang permanen)';
      break;
    case 'DELETE':
      statusText = 'Konfirmasi Hapus Data';
      actionType = 'menghapus data dari tabel';
      break;
    case 'UPDATE':
      statusText = 'Konfirmasi Perbarui Data';
      actionType = 'memperbarui data pada tabel';
      break;
    case 'INSERT':
      statusText = 'Konfirmasi Tambah Data';
      actionType = 'menambahkan data baru ke tabel';
      break;
    case 'EXEC':
      statusText = 'Konfirmasi Eksekusi Prosedur';
      actionType = 'menjalankan perintah Stored Procedure';
      break;
    default:
      statusText = 'Konfirmasi Diperlukan';
      actionType = 'menjalankan perintah sistem';
  }
}

narrativeOverride = 
  `PERHATIAN: Anda akan ${actionType} pada objek ${table} di database ${database}.\n` +
  `Aksi ini mempengaruhi sekitar ${affectedRows} baris data.\n\n` +
  `Silakan konfirmasi tindakan Anda.`;

return {
  json: {
    status_text: statusText,
    status_type: statusType,
    fallback_narrative: narrativeOverride,
    metadata: {
      database: database,
      table: table,
      row_count: affectedRows,
      timestamp: new Date().toLocaleString('id-ID'),
      query: query,
      query_type: detectQueryType(query),
      estimated_impact: affectedRows
    },
    llm_context: {
      action_type: actionType,
      query_type: detectQueryType(query),
      table_name: table,
      database_name: database,
      affected_rows: affectedRows
    },
    data: []
  }
};

const query = $json.query || "";
const hasQuery = $json.has_query || false;
const affectedRows = $json.affected_rows || 0;
const table_name = $json.table_name || "";

console.log('=== SHOW DRAFT DEBUG ===');
console.log('query:', query);
console.log('hasQuery:', hasQuery);
console.log('affectedRows:', affectedRows);
console.log('table_name:', table_name);

let narrative = "";
let statusType = "info";

if (!hasQuery || !query) {
  narrative = "Tidak ada draft query yang tersimpan";
  statusType = "danger";
} else {
  narrative = 
    'DRAFT QUERY YANG TIDAK DIJALANKAN\n\n' +
     `Query berikut tidak dieksekusi. Salin dan jalankan manual di SSMS:\n\n` +
    `${query}\n\n` +
    `Estimasi Dampak: ~${affectedRows} baris`;
}

return {
  output: JSON.stringify({
    status_text: "Draft Query",
    status_type: statusType,
    narrative: narrative,
    metadata: {
    database: "TestDB",
    table_name: table_name,
    row_count: affectedRows,
    timestamp: new Date().toLocaleString('id-ID'),
    query: query,
    estimated_impact: affectedRows
    },
    data: [],
    dashboard_url: "#"
  })
};

const rows = $input.all();

if (rows.length === 0) {
  return { 
    query: "", 
    has_query: false,
    table_name: "-",
    affected_rows: 0,
    session_id: "",
    pending_id: null,
    expires_at: "",
    error: "expired",
    message: "Query sudah kadaluarsa (>5 menit). Silakan kirim perintah baru."
  };
}

const row = rows[0].json;
const query = row.pending_query || "";

if (!query) {
  return { 
    query: "", 
    has_query: false,
    table_name: row.table_name || "-",
    affected_rows: row.affected_rows || 0,
    session_id: row.session_id || "",
    pending_id: row.pending_id || null,
    expires_at: row.expires_at || "",
    error: "empty",
    message: "Masa pakai query telah habis, silakan kirim perintah baru"
  };
}

return { 
  query: query, 
  has_query: true,
  table_name: row.table_name || "-",
  affected_rows: row.affected_rows || 0,
  session_id: row.session_id || "",
  pending_id: row.pending_id || null,
  expires_at: row.expires_at || "",
  error: "",
  message: ""
};

const rows = $input.all();

if (rows.length === 0) {
  return { 
    query: "", 
    has_query: false, 
    affected_rows: 0,
    table_name : ""
  };
}

const row = rows[0].json;

console.log('=== EXTRACT QUERY DEBUG ===');
console.log('Row:', JSON.stringify(row));
console.log('affected_rows:', row.affected_rows);

return { 
  query: row.pending_query || "", 
  has_query: !!row.pending_query,
  affected_rows: row.affected_rows || 0,
  table_name: row.table_name || ""
};

