{{ (() => {
  const database = $('Parse Code').item.json.database || 'TestDB';

  let query = '';
  try {
    query = $('Format Pending').item.json.query || '';
  } catch (e) {
    query = $json.query || '';
  }

  if (!query) return 'SELECT 1 AS no_query';

  const upper = query.toUpperCase().trim();

  // ==========================================
  // AUTO-FIX sp_rename: hapus prefix 'dbo.' 
  // ==========================================
  if (/SP_RENAME/i.test(query)) {
    let fixed = query;

    // Pattern 1: 'dbo.tablename.columnname' → 'tablename.columnname'
    fixed = fixed.replace(
      /(sp_rename\s+['"])dbo\./gi,
      '$1'
    );

    // Pattern 2: '[dbo].[tablename].[columnname]' → '[tablename].[columnname]'
    fixed = fixed.replace(
      /(sp_rename\s+['"])\[dbo\]\./gi,
      '$1'
    );

    return `USE [${database}]; ${fixed}`;
  }

  // Auto-fix CREATE VIEW/PROCEDURE
  let fixed = query;
  let fixedUpper = fixed.toUpperCase().trim();

  if (fixedUpper.startsWith('CREATE VIEW')) {
    fixed = fixed.replace(/^CREATE\s+VIEW/i, 'CREATE OR ALTER VIEW');
    fixedUpper = fixed.toUpperCase().trim();
  }
  if (fixedUpper.startsWith('CREATE PROCEDURE')) {
    fixed = fixed.replace(/^CREATE\s+PROCEDURE/i, 'CREATE OR ALTER PROCEDURE');
    fixedUpper = fixed.toUpperCase().trim();
  }

  const isDDL = 
    fixedUpper.startsWith('CREATE OR ALTER PROCEDURE') ||
    fixedUpper.startsWith('ALTER PROCEDURE') ||
    fixedUpper.startsWith('CREATE OR ALTER VIEW') ||
    fixedUpper.startsWith('ALTER VIEW') ||
