const query = (firstItem.original_query || "").toUpperCase();
const column = firstItem.column_name || "";
const oldCol = firstItem.old_column || "";
const newCol = firstItem.new_column || "";
const rawQuery = firstItem.original_query || "";
const isSpRename =  query.includes("SP_RENAME");

let parsedOldCol = oldCol;
let parsedNewCol = newCol;
let parsedTable = table;

if (isSpRename) {
  const rm = rawQuery.match(/sp_rename\s+['"]([^'"]+)['"]\s*,\s*['"]([^'"]+)['"]/i);
  if (rm) {
    const parts = rm[1].split('.');
    if (parts.length >= 3) {
      parsedTable = parts.slice(0, parts.length - 1).join('.');
      parsedOldCol = parts[parts.length - 1];
    } else if (parts.length === 2) {
      parsedTable = parts[0];
      parsedOldCol = parts[1];
    }
    parsedNewCol = rm[2];
  }
}

let narrative = "";

const isCountQuery = query.includes("COUNT(");
const isSumQuery = query.includes("SUM(");
const isAvgQuery = query.includes("AVG(");
const isMaxQuery = query.includes("MAX(");
const isMinQuery = query.includes("MIN(");
const isAggregateQuery = isCountQuery || isSumQuery || isAvgQuery || isMaxQuery || isMinQuery;

if (queryType === "SELECT") {
  if (isAggregateQuery && items.length > 0) {
    const dataRow = items[0].json;
    const fieldNames = Object.keys(dataRow).filter(k => 
      !['row_count', 'query_type', 'timestamp', 'database_name', 
        'table_name', 'original_query', 'user_session', 
        'column_name', 'column_names', 'old_column', 'old_column_name', 
        'new_column', 'new_column_name'].includes(k)
    );

    const aggField = fieldNames[0];
    const aggValue = aggField ? dataRow[aggField] : null;
    const formattedValue = formatNumber(aggValue);

    if (isCountQuery) {
      narrative = `Jumlah data pada tabel ${table} adalah ${formattedValue}.`;
    } else if (isSumQuery) {
      narrative = `Total data yang dimiliki ada ${formattedValue}.`;
    } else if (isAvgQuery) {
      narrative = `Rata-rata dari tabel ${table} adalah ${formattedValue}.`;
    } else if (isMaxQuery) {
      narrative = `Nilai maksimum dari tabel ${table} adalah ${formattedValue}.`;
    } else if (isMinQuery) {
      narrative = `Nilai minimum dari tabel ${table} adalah ${formattedValue}.`;
    }
  }

  else if (items.length === 0) {
    narrative = `Tidak ada data yang ditemukan untuk kriteria tersebut.`;
  } else {
    narrative = `Ditemukan ${items.length} baris data dari tabel ${table}.`;
  }

} else if (queryType === "UPDATE") {
  narrative = items.length === 1
    ? `Data berhasil diperbarui, data kolom ${column} pada tabel ${table} telah diubah.`
    : `Data berhasil diperbarui. Sebanyak ${items.length} baris pada tabel ${table} telah diubah.`;

} else if (queryType === "INSERT") {
  narrative = items.length === 1
    ? `Data baru berhasil ditambahkan ke tabel ${table}.`
    : `Sebanyak ${items.length} baris data baru berhasil ditambahkan ke tabel ${table}.`;

} else if (queryType === "DELETE") {
  narrative = items.length === 1
    ? `Data berhasil dihapus dari tabel ${table}.`
    : `Sebanyak ${items.length} baris data berhasil dihapus dari tabel ${table}.`;

} else if (queryType === "CREATE") {
  narrative = `Tabel baru ${table} berhasil dibuat dengan daftar kolom: ${column}.`;

} else if (queryType === "ALTER") {
  narrative = `Struktur tabel ${table} berhasil diubah.`;

} else if (queryType === "EXEC" && isSpRename && parsedOldCol && parsedNewCol) {
  narrative = `Kolom ${parsedOldCol} pada tabel ${parsedTable} berhasil diubah menjadi ${parsedNewCol}.`;

} else if (queryType === "EXEC") {
  narrative = 'Stored Procedure ' + table + ' berhasil dijalankan. Dikembalikan ' + items.length + ' row.';

} else if (queryType === "CREATE VIEW") {
  narrative = 'View ' + table + ' telah berhasil dibuat';

} else if (queryType === "ALTER VIEW") {
  narrative = 'Struktur View ' + table + ' berhasil diubah';

} else if (queryType === "DROP VIEW") {
  narrative = 'View ' + table + ' telah berhasil di hapus dari database';

} else if (queryType === "DROP") {
  narrative = `Objek ${table} telah dihapus dari database.`;

} else {
  narrative = `Query berhasil dijalankan pada tabel ${table}.`;
}

function formatNumber(num) {
  if (num === null || num === undefined) return "0";
  if (typeof num === 'string') return num;
  return num.toLocaleString('id-ID');
}

return {
  narrative: narrative,
  ...firstItem
};

// ==========================================
