  if (match) tableName = match[1].replace(/[\[\]]/g, '');

} else {
  // Sumber 2: Confirm (pending query)
  try {
    const formatPending = $('Format Pending').item.json;
    query = formatPending.query || '-';

    const loadPending = $('Load Pending Query').item.json;
