  case 'ALTER TABLE':       narrative = 'Struktur tabel "' + tableName + '" berhasil diubah.'; break;
  case 'DELETE':            narrative = affectedRows + ' baris data berhasil dihapus dari "' + tableName + '".'; break;
  case 'UPDATE':            narrative = affectedRows + ' baris data berhasil diperbarui pada "' + tableName + '".'; break;
  case 'INSERT':            narrative = affectedRows + ' baris data berhasil ditambahkan ke "' + tableName + '".'; break;
