    const m = q.match(/EXEC(?:UTE)?\s+(?:\[?dbo\]?\.)?(\[[^\]]+\]|[a-zA-Z0-9_]+)/i);
    if (m && m[1]) return m[1].replace(/[\[\]]/g, '');
    return '-';
  }

  const backupMatch = q.match(/BACKUP\s+(?:DATABASE|LOG)\s+(?:\[([^\]]+)\]|([a-zA-Z0-9_]+))/i);
  if (backupMatch) return (backupMatch[1] || backupMatch[2] || '-');

  const tableRegex = /(?:FROM|JOIN|UPDATE|INTO|DELETE\s+FROM)\s+([^\(\)\s,;]+)/gi;

  let match;
  let tables = [];

  while ((match = tableRegex.exec(q)) !== null) {
    let rawName = match[1];

    if (rawName === '(' || /^(SELECT|WHERE|GROUP|ORDER|AS|INNER|LEFT|RIGHT|OUTER|CROSS)$/i.test(rawName)) {
