  statusType = 'confirm_alter_foreign_key';
  statusText = 'Konfirmasi Tambah Foreign Key';
  actionType = "menambahkan relasi antar tabel (Foreign Key)";
} else if (subType === 'alter_table') {
  statusType = 'confirm_alter_table';
  statusText = 'Konfirmasi Perubahan Struktur Tabel';
  actionType = "mengubah struktur tabel";
} 

else {
  const qType = detectQueryType(query);
  switch(qType) {
    case 'CREATE PROCEDURE':
      statusText = 'Konfirmasi Buat Stored Procedure';
      actionType = 'membuat Stored Procedure baru';
      break;
    case 'ALTER PROCEDURE':
      statusText = 'Konfirmasi Ubah Stored Procedure';
      actionType = 'mengubah Stored Procedure';
      break;
    case 'DROP PROCEDURE':
      statusText = 'Konfirmasi Hapus Stored Procedure';
      actionType = 'menghapus Stored Procedure secara permanen';
      break;
    case 'CREATE VIEW':
      statusText = 'Konfirmasi Buat View';
      actionType = 'membuat View baru';
      break;
    case 'ALTER VIEW':
      statusText = 'Konfirmasi Ubah View';
      actionType = 'mengubah View';
      break;
    case 'DROP VIEW':
      statusText = 'Konfirmasi Hapus View';
      actionType = 'menghapus View secara permanen';
      break;
    case 'DROP TABLE':
      statusText = 'Konfirmasi Hapus Tabel';
      actionType = 'menghapus seluruh tabel beserta datanya (SANGAT BERBAHAYA)';
      break;
    case 'TRUNCATE':
      statusText = 'Konfirmasi Kosongkan Tabel';
      actionType = 'mengosongkan seluruh isi tabel (data akan hilang permanen)';
      break;
    case 'DELETE':
      statusText = 'Konfirmasi Hapus Data';
      actionType = 'menghapus data dari tabel';
      break;
    case 'UPDATE':
      statusText = 'Konfirmasi Perbarui Data';
      actionType = 'memperbarui data pada tabel';
      break;
    case 'INSERT':
      statusText = 'Konfirmasi Tambah Data';
      actionType = 'menambahkan data baru ke tabel';
      break;
    case 'EXEC':
      statusText = 'Konfirmasi Eksekusi Prosedur';
      actionType = 'menjalankan perintah Stored Procedure';
      break;
    default:
      statusText = 'Konfirmasi Diperlukan';
      actionType = 'menjalankan perintah yang mengubah sistem';
  }
}

narrativeOverride = 
  `PERHATIAN: Anda akan ${actionType} pada objek ${table} di database ${database}.\n` +
  `Aksi ini mempengaruhi sekitar ${affectedRows} baris data.\n\n` +
  `Silakan konfirmasi tindakan Anda.`;

return {
  json: {
    status_text: statusText,
    status_type: statusType,
    fallback_narrative: narrativeOverride,
    metadata: {
      database: database,
      table: table,
      row_count: affectedRows,
      timestamp: new Date().toLocaleString('id-ID'),
      query: query,
      query_type: detectQueryType(query),
      estimated_impact: affectedRows,
      column_name: columnName,       
      old_column: oldColumn,         
      new_column: newColumn          
    },
    llm_context: {
      action_type: actionType,
      query_type: detectQueryType(query),
      table_name: table,
      database_name: database,
      affected_rows: affectedRows,
      old_column: oldColumn,
      new_column: newColumn
    },
    data: []
  }
};

let errorNarrative = "";
try {
  errorNarrative = $('Error Narative AI').item.json.text || $('Error Narative AI').item.json.output || "";
} catch(e) {}

return {
  json: {
    status_text: $('Generate Error ').item.json.status_text,
    status_type: $('Generate Error ').item.json.status_type,
    narrative: errorNarrative, 
    metadata: {
      database: $('Generate Error ').item.json.database,
      table: $('Generate Error ').item.json.table,
      row_count: 0,
      timestamp: $('Generate Error ').item.json.timestamp,
      query: $('Generate Error ').item.json.query,
      query_type: 'ERROR'
    },
    data: [],
    dashboard_url: ""
  }
}

const metadata = $('Generate Status').item.json;
const timestamp = metadata.timestamp || "-";
const queryType = (metadata.query_type || "SELECT").toUpperCase();
const database = metadata.database_name || "-";
const table = metadata.table_name || "-";
const query = metadata.original_query || "-";
const column = metadata.column_name || "-";
const oldCol = metadata.old_column || "-";
const newCol = metadata.new_column || "-";

let narrative = "";
try {
  narrative = $('Succes Narrative AI').item.json.text || $('Succes Narrative AI').item.json.output || "";
} catch (e) {
  narrative = "";
}

let sanitizedData = [];
const METADATA_FIELDS_TO_STRIP = [
  'row_count', 'query_type', 'timestamp', 'database_name',
  'table_name', 'original_query', 'user_session', 'session_id',
  'column_name', 'column_names', 'old_column', 'new_column', 'pending_id'
];

const isTableQuery = ['SELECT', 'EXEC', 'WITH'].includes(queryType);

if (isTableQuery) {
  try {

    const executorItems = $('Executor Query').all();

    sanitizedData = executorItems.map(item => {
      const cleanRow = { ...item.json };
      METADATA_FIELDS_TO_STRIP.forEach(field => delete cleanRow[field]);
      return Object.keys(cleanRow).length === 0 ? null : cleanRow;
    }).filter(Boolean).slice(0, 100); // Tetap batasi maksimal 100 untuk UI

  } catch (e) {
    sanitizedData = []; // Jika gagal, array kosong
  }
}

// 4. Susun objek hasil akhir
let result = {
  status_text: "",
  status_type: "success",
  narrative: "",
  metadata: {
    database: database,
    table: table,
    row_count: sanitizedData.length, // Sesuaikan jumlah baris dengan data yang ditarik
    timestamp: timestamp,
    query: query,
    query_type: queryType,
    column: column,
    old_column: oldCol,
    new_column: newCol
  },
  data: sanitizedData, // Ini yang akan dirender jadi tabel di Angular
  dashboard_url: "" // Sesuaikan dengan base URL Anda jika ada
};

// 5. Tentukan Status & Narasi
if (queryType === "SELECT") {
  result.status_text = "Data Berhasil Diambil";
  result.status_type = "success";
  result.narrative = narrative || `Ditemukan ${result.metadata.row_count} baris data dari tabel ${table}.`;

} else if (queryType === "UPDATE") {
  result.status_text = "Data Berhasil Diperbarui";
  result.status_type = "success";
  result.narrative = narrative || `Data pada tabel ${table} telah diperbarui.`;

} else if (queryType === "INSERT") {
  result.status_text = "Data Berhasil Ditambahkan";
  result.status_type = "success";
  result.narrative = narrative || `Data baru telah ditambahkan ke tabel ${table}.`;

} else if (queryType === "DELETE") {
  result.status_text = "Data Berhasil Dihapus";
  result.status_type = "warning";
  result.narrative = narrative || `Data telah dihapus dari tabel ${table}.`;

} else {
  result.status_text = "Query Berhasil Dijalankan";
  result.status_type = "success";
  result.narrative = narrative || `Perintah berhasil dieksekusi.`;
}

return { json: result };

const warningData = $('Warning').item.json;

let aiNarrative = "";
try {
  aiNarrative = $('Warning Narrative AI').item.json.text || $('Warning Narrative AI').item.json.output || "";
} catch (e) {
  aiNarrative = "";
}

const finalNarrative = aiNarrative || warningData.fallback_narrative;

return {
  json: {
    status_text: warningData.status_text,
    status_type: warningData.status_type,
    narrative: finalNarrative, 
    metadata: warningData.metadata, 
    data: warningData.data
  }
};

let aiNarrative = "";
try {
  aiNarrative = $('Forbidden Narrative AI').item.json.text || $('Forbidden Narrative AI').item.json.output || "";
} catch (e) {
  aiNarrative = "Operasi ini tidak diizinkan oleh sistem karena termasuk dalam kategori berbahaya. Silakan hubungi Administrator.";
}

return {
  json: {
    status_text: $('Generate Status Forbidden').item.json.status_text,
    status_type: $('Generate Status Forbidden').item.json.status_type,
    narrative: aiNarrative,
    metadata: $('Generate Status Forbidden').item.json.metadata,
    data: []
  }
};

const query = $json.query || '';
const queryUpper = query.toUpperCase();

let reasonContext = 'Pelanggaran keamanan umum (operasi berbahaya).';

if (queryUpper.includes('DROP DATABASE')) {
  reasonContext = 'Penghapusan database secara permanen (DROP DATABASE).';
} else if (queryUpper.includes('CREATE USER') || queryUpper.includes('ALTER USER') || queryUpper.includes('DROP USER')) {
  reasonContext = 'Manajemen user database (Pembuatan/Perubahan/Penghapusan User).';
} else if (queryUpper.includes('GRANT') || queryUpper.includes('REVOKE') || queryUpper.includes('DENY')) {
  reasonContext = 'Pengaturan hak akses/izin (GRANT/REVOKE/DENY).';
} else if (queryUpper.includes('CREATE ROLE') || queryUpper.includes('ALTER ROLE') || queryUpper.includes('DROP ROLE')) {
  reasonContext = 'Manajemen role database.';
} else if (queryUpper.includes('BACKUP')) {
  reasonContext = 'Operasi Backup Database/Log.';
} else if (queryUpper.includes('INDEX')) {
  reasonContext = 'Pembuatan Index (perubahan performa).';
} else if ((queryUpper.startsWith('UPDATE') || queryUpper.startsWith('DELETE')) && !/\bWHERE\b/i.test(query)) {

  reasonContext = 'Operasi Update atau Delete massal TANPA klausa WHERE (sangat berbahaya karena mengubah/menghapus seluruh isi tabel).';
}

return {
  ...$json,
  llm_context: {
    query: query,
    reason: reasonContext
  }
};

return {
  status_text: 'Operasi Ditolak',
  status_type: 'forbidden',
  query: $json.query || '',
  narrative: '',
  metadata: {
  database_name: 'TestDB',
  table_name: '-',
  row_count: 0,
  query_type: $json.query ? $json.query.trim().split(/\s+/)[0].toUpperCase() : 'UNKNOWN',
  query: $json.query || '',
  estimated_impact: 0,
  timestamp: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }) + ', ' + new Date().toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric' })
  }
};

